pages/account/orders/details:
---
blog:
    recent_posts:
        limit: {{theme_settings.homepage_blog_posts_count}}
---

{{#partial "page"}}
{{inject 'selectItem' (lang 'forms.validate.account.reorder.select_item')}}

{{> components/common/breadcrumbs breadcrumbs=breadcrumbs}}
<h2 class="page-heading title">{{lang 'account.orders.details.heading' number=order.id}}</h2>
{{> components/account/navigation account_page='orders'}}

<div class="account">
    <div class="account-body">
        {{#each order.status_messages}}
            {{> components/common/alert/alert-info message}}
        {{/each}}
        <div class="account-content account-content--fixedSmall">
            {{> components/account/order-contents order=order}}

            <dl class="account-orderTotal">
                {{#each order.total_rows}}
                    {{#if value.value}}
                        <dt class="account-orderTotal-key">{{label}}:</dt>
                        <dd class="account-orderTotal-value">{{value.formatted}}</dd>
                    {{/if}}
                {{/each}}
            </dl>
        </div>

        <aside class="account-sidebar">
            <section class="account-sidebar-block">
                <h3 class="account-heading">{{lang 'account.orders.details.order_details'}}</h3>
                <dl class="definitionList">
                    <dt class="definitionList-key">{{lang 'account.orders.details.order_status'}}</dt>
                    <dd class="definitionList-value">{{order.status_text}}</dd>
                    <dt class="definitionList-key">{{lang 'account.orders.details.payment_date'}}</dt>
                    <dd class="definitionList-value">{{order.date}}</dd>
                    <dt class="definitionList-key">{{lang 'account.orders.details.order_total'}}</dt>
                    <dd class="definitionList-value">{{order.total.formatted}}</dd>
                    {{#if order.payment_method}}
                        <dt class="definitionList-key">{{lang 'account.orders.details.payment_method'}}</dt>
                        <dd class="definitionList-value">
                            {{order.payment_method}}
                            {{#if order.card_number_last_four}}
                                {{lang 'account.orders.details.card_ending' card=order.card_number_last_four}}
                            {{/if}}
                        </dd>
                    {{/if}}
                    {{#if order.order_instructions}}
                        <dt class="order-payments-description">{{lang 'account.orders.details.how_to_pay'}}</dt>
                        <dd class="order-payments-value order-payments-value--long">{{nl2br order.order_instructions}}</dd>
                    {{/if}}
                </dl>

                <button data-print-invoice="{{order.invoice_url}}" class="button button--primary">{{lang 'account.orders.details.print_invoice'}}</button>
            </section>

            {{#if order.shipping_address}}
                <section class="account-sidebar-block">
                    <h3 class="account-heading">{{lang 'account.orders.details.ship_to'}}</h3>
                    <ul class="account-order-address">
                        <li>{{{ sanitize order.shipping_address.full_name}}}</li>
                        <li>{{{ sanitize order.shipping_address.company}}}</li>
                        <li>{{{ sanitize order.shipping_address.address_lines.[0]}}}</li>
                        <li>{{{ sanitize order.shipping_address.address_lines.[1]}}}</li>
                        <li>{{{ sanitize order.shipping_address.city}}}, {{{ sanitize order.shipping_address.state}}} {{{ sanitize order.shipping_address.zip}}}</li>
                        <li>{{{ sanitize order.shipping_address.country}}}</li>
                    </ul>
                </section>
            {{/if}}
            {{#if order.pickup_address}}
            <section class="account-sidebar-block">
                <h3 class="account-heading">{{lang 'account.orders.details.pickup'}}</h3>
                {{#each order.pickup_address}}
                <dl class="definitionList">
                    <dt class="definitionList-key">{{lang 'account.orders.details.pickup_method'}}</dt>
                    <dd class="definitionList-value">{{sanitize pickup_method_display_name}}</dd>
                </dl>

                <ul class="account-order-address">
                    <li><b>{{{ sanitize location_name}}}</b></li>
                    <li>{{{ sanitize location_line_1}}}</li>
                    <li>{{{ sanitize location_line_2}}}</li>
                    <li>{{{ sanitize location_city}}}, {{{ sanitize location_state}}}, {{{ sanitize location_zip}}}</li>
                    <li>{{{ sanitize location_country_name}}}</li>
                </ul>

                <dl class="definitionList">
                    {{#if location_phone}}
                    <dt class="definitionList-key">{{lang 'account.orders.details.phone'}}</dt>
                    <dd class="definitionList-value">{{{ sanitize location_phone}}}</dd>
                    {{/if}}
                    {{#if order.pickup_address.location_email}}
                    <dt class="definitionList-key">{{lang 'account.orders.details.email'}}</dt>
                    <dd class="definitionList-value">{{{ sanitize location_email}}}</dd>
                    {{/if}}
                </dl>

                <ul class="account-order-address">
                    <li><b>{{{ lang 'account.orders.details.opening_hours'}}}</b></li>
                    <li>{{{ sanitize collection_time_description}}}</li>
                </ul>
                {{/each}}
            </section>
            {{else}}
                {{#if order.has_multiple_shipping_addresses}}
                    <section class="account-sidebar-block">
                        <h3 class="account-heading">{{lang 'account.orders.details.ship_to'}}</h3>
                        <div class="account-order-address">
                            {{lang 'account.orders.details.ship_to_multi_text'}}
                        </div>
                    </section>
                {{/if}}
            {{/if}}

            <section class="account-sidebar-block">
                <h3 class="account-heading">{{lang 'account.orders.details.bill_to'}}</h3>
                <ul class="account-order-address">
                    <li>{{{ sanitize order.billing_address.full_name}}}</li>
                    <li>{{{ sanitize order.billing_address.company}}}</li>
                    <li>{{{ sanitize order.billing_address.address_lines.[0]}}}</li>
                    <li>{{{ sanitize order.billing_address.address_lines.[1]}}}</li>
                    <li>{{{ sanitize order.billing_address.city}}}, {{{ sanitize order.billing_address.state}}} {{{ sanitize order.billing_address.zip}}}</li>
                    <li>{{{ sanitize order.billing_address.country}}}</li>
                </ul>
            </section>

            {{#if shipments}}
                <section class="account-sidebar-block">
                    <h3 class="account-heading">{{lang 'account.orders.details.shipments.header'}}</h3>
                    {{#each shipments}}
                        <dl class="definitionList">
                            <dt class="definitionList-key">{{lang 'account.orders.details.shipments.date'}}:</dt>
                            <dd class="definitionList-value">{{date_shipped}}</dd>
                            <dt class="definitionList-key">{{lang 'account.orders.details.shipments.method'}}:</dt>
                            <dd class="definitionList-value">{{shipping_provider}}</dd>
                            <dt class="definitionList-key">{{lang 'account.orders.details.shipments.link'}}:</dt>
                            <dd class="definitionList-value">
                                {{#if shipping_track.url}}
                                    <a href="{{shipping_track.url}}">
                                {{/if}}

                                {{#if show_shipping_method}}
                                    {{shipping_track.number}} &mdash; {{shipping_method}}
                                {{else}}
                                    {{shipping_track.number}}
                                {{/if}}

                                {{#if shipping_track.url}}
                                    </a>
                                {{/if}}
                            </dd>
                        </dl>
                    {{/each}}
                </section>
            {{/if}}

            {{#if order.comments}}
                <section class="account-sidebar-block">
                    <h3 class="account-heading">{{lang 'account.orders.details.comments'}}</h3>
                    <p>{{order.comments}}</p>
                </section>
            {{/if}}

            <section class="account-sidebar-block">
                <h3 class="account-heading">{{lang 'account.orders.details.actions'}}</h3>
                <div class="order-details-info">
                    <form class="account-reorder-form" action="{{order.reorder_url}}" method="post" data-account-reorder-form>
                        <input type="hidden" name="orderid" value="{{order.id}}">
                        {{#each order.items}}
                            {{#if show_reorder}}
                                <input type="hidden" name="reorderitem[{{order_product_id}}]">
                            {{/if}}
                        {{/each}}
                        <input type="submit" class="button button--primary" value="{{lang 'account.orders.details.reorder'}}">
                    </form>
                    {{#if settings.returns_enabled}}
                        {{#if order.is_complete}}
                            <a href="{{order.return_url}}" class="button button--primary">{{lang 'account.orders.details.return'}}</a>
                        {{/if}}
                    {{/if}}
                </div>
            </section>
        </aside>

    </div>
</div>
{{/partial}}
{{> layout/base}}

components/ob-custom/global/ob-header:
{{inject 'theme_settings' theme_settings}}
{{inject 'main_settings' settings}}

<header class="header" role="banner">
    <div class="header--top">
        <div class="{{#if theme_settings.logo-position '==' 'left'}}logo-left {{else if theme_settings.logo-position '==' 'right'}}logo-right {{/if}}container">
            <a href="#" class="mobileMenu-toggle" data-mobile-menu-toggle="menu">
                <span class="mobileMenu-toggleIcon">Toggle menu</span>
            </a>

            <div class="navPages-quickSearch ob-desktop"></div>

            {{#if page_type '===' 'default'}}
                <h1 class="header-logo header-logo--{{theme_settings.logo-position}}">
                    {{> components/common/store-logo}}
                </h1>
            {{else}}
                <div class="header-logo header-logo--{{theme_settings.logo-position}}">
                    {{> components/common/store-logo}}
                </div>
            {{/if}}

            {{> components/ob-custom/global/ob-navigation}}
        </div>
    </div>
    <div class="header--bottom">
        <div class="container">
            <div class="header-promo ob-desktop ob-tablet-hidden">
                {{#if theme_settings.show_header_promo}}
                    {{> components/ob-custom/global/ob-header-promo}}
                {{/if}}
            </div>
            <div class="navPages-container" id="menu" data-menu>
                {{> components/ob-custom/global/ob-navigation-menu}}
            </div>
            <div class="header-beta-nav ob-desktop ob-tablet-hidden">
                {{#if theme_settings.show_gift_blog_links}}
                    {{#if settings.gift_certificates_enabled}}
                        <a class="beta-link gift-link"
                           href="{{urls.gift_certificate.purchase}}"
                           aria-label="{{lang 'common.gift_cert'}}"
                        >
                            {{#if theme_settings.theme_type '==' 'light'}}
                                <svg><use xlink:href="#icon-gift" /></svg>
                            {{/if}}
                            {{lang 'common.gift_cert'}}
                        </a>
                    {{/if}}
                    {{#if settings.blog_enabled}}
                        <a class="beta-link blog-link"
                           href="{{blog.url}}"
                           aria-label="{{blog.name}}"
                        >
                            {{blog.name}}
                        </a>
                    {{/if}}
                {{/if}}
            </div>
        </div>
    </div>
</header>

{{#if banners.top}}
<div class="banners" data-banner-location="top">
    {{#each (limit banners.top_metadata 1)}}
    <div class="banner" data-event-type="promotion" data-entity-id="{{this.id}}" data-name="{{this.banner-name}}" data-position="{{this.location}}" data-banner-id="{{this.banner-name}}">
        <div data-event-type="promotion-click">
            {{{this.content}}}
        </div>
    </div>
    {{/each}}
</div>
{{/if}}

components/ob-custom/global/ob-footer:
{{#if banners.bottom}}
    {{#if settings.data_tag_enabled}}
        <div class="banners" data-banner-location="bottom">
            {{#each (limit banners.bottom_metadata 1)}}
                <div class="banner" data-event-type="promotion" data-entity-id="{{this.id}}" data-name="{{this.banner-name}}" data-position="{{this.location}}" data-name="{{this.banner-name}}">
                    <div data-event-type="promotion-click">
                        {{{this.content}}}
                    </div>
                </div>
            {{/each}}
        </div>
    {{else}}
        <div class="banners" data-banner-location="bottom">
            <div class="banner">
                {{{limit banners.bottom 1}}}
            </div>
        </div>
    {{/if}}
{{/if}}

{{{region name="above_footer"}}}

<footer class="footer" role="contentinfo">
    <div class="footer-inner">
        {{#all theme_settings.is_night (if theme_settings.footer-backgroundImage '==' 'default')}}
            <img class="footer-bg ob-desktop" src="{{cdn 'assets/img/ob-custom/footer-bg-desktop.svg'}}" alt="Footer background" />
            <img class="footer-bg ob-mobile" src="{{cdn 'assets/img/ob-custom/footer-bg-mobile.svg'}}" alt="Footer background" />
        {{/all}}
        {{#all theme_settings.is_night (if theme_settings.footer-backgroundImage '==' 'custom') theme_settings.footer-backgroundImage-file}}
            <img class="footer-bg ob-desktop" src="{{getImageManagerImage theme_settings.footer-backgroundImage-file}}" alt="Footer background" />
            <img class="footer-bg ob-mobile" src="{{getImageManagerImage theme_settings.footer-backgroundImage-file-mobile}}" alt="Footer background" />
        {{/all}}
        <h2 class="footer-title-sr-only">Footer</h2>
        <div class="container">
            <div class="ob-news-section">
                {{#if theme_settings.footer_show_newsletter}}
                    <article class="footer-info-col" data-section-type="newsletterSubscription">
                        {{> components/ob-custom/global/footer/ob-subscription-form}}
                    </article>
                {{/if}}

                {{#if social_media}}
                    <article class="footer-info-col footer-info-col--small footer-social" data-section-type="footer-webPages">
                        <h3 class="footer-info-heading">{{theme_settings.footer_social_title}}</h3>
                        {{> components/common/social-links}}
                    </article>
                {{/if}}
            </div>
            <div class="ob-nav-section">
                <article class="footer-info-col footer-info-col--small" data-section-type="footer-categories">
                    <h3 class="footer-info-heading">{{theme_settings.footer_shop_title}}</h3>
                    <ul class="footer-info-list">
                        {{#each categories}}
                            <li>
                                <a href="{{url}}">{{name}}</a>
                            </li>
                        {{/each}}
                        {{#if settings.gift_certificates_enabled}}
                            <li>
                                <a href="{{urls.gift_certificate.purchase}}">
                                    {{lang 'common.gift_cert'}}
                                </a>
                            </li>
                        {{/if}}
                        {{#if theme_settings.footer_brands_link}}
                            <li>
                                <a href="/brands">View Brands</a>
                            </li>
                        {{/if}}
                    </ul>
                </article>

                {{#if theme_settings.footer_learn_column}}
                    <article class="footer-info-col footer-info-col--small" data-section-type="footer-webPages">
                        <h3 class="footer-info-heading">{{theme_settings.footer_learn_title}}</h3>
                        <ul class="footer-info-list">
                            {{#each pages}}
                                <li>
                                    <a href="{{url}}">
                                        {{name}}
                                    </a>
                                </li>
                            {{/each}}
                        </ul>
                    </article>
                {{/if}}

                {{#if theme_settings.footer_support_column}}
                    <article class="footer-info-col footer-info-col--small" data-section-type="footer-webPages">
                        <h3 class="footer-info-heading">{{theme_settings.footer_support_title}}</h3>
                        <ul class="footer-info-list">
                            {{> components/ob-custom/global/footer/ob-support}}
                        </ul>
                    </article>
                {{/if}}

                {{#any theme_settings.footer_show_address theme_settings.show_footer_hours}}
                    <article class="footer-info-col footer-info-col--small" data-section-type="storeInfo">
                        <h3 class="footer-info-heading">{{theme_settings.footer_address_title}}</h3>

                        {{#all settings.address theme_settings.footer_show_address}}
                            <address>{{nl2br settings.address}}</address>
                        {{/all}}

                        {{#if theme_settings.show_footer_hours}}
                            <p>{{theme_settings.store_hours}}</p>
                        {{/if}}
                    </article>
                {{/any}}
            </div>

            <div class="ob-copyright-section">
                {{#if theme_settings.show_copyright_footer}}
                    <div class="footer-copyright footer-store-date">
                        <p class="powered-by">
                            &copy; {{moment format="YYYY"}} {{settings.store_name}} | 
                            <a href="{{urls.sitemap}}">{{lang 'sitemap.page_title'}}</a> 
                        </p>
                    </div>
                {{/if}}

                {{> components/ob-custom/global/footer/ob-payment-icons}}

                {{#if theme_settings.show_copyright_footer}}
                    {{#if theme_settings.footer_obundle}}
                        <div class="footer-copyright footer-obundle">
                            <p class="designed-by">
                                Designed &amp; developed by 
                                <a href="http://www.obundle.com">
                                    oBundle
                                    <svg><use xlink:href="#icon-obundle" /></svg>
                                </a>
                            </p>
                        </div>
                    {{/if}}
                {{/if}}
            </div>
        </div>
        {{{region name="ssl_site_seal--global"}}}
    </div>
</footer>

